INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('chest-wall-3-0', '2026.09.2', '{"id":"chest-wall-3-0","unitId":"chest-wall","version":"2026.09.2","mode":3,"difficulty":0,"ordered":true,"briefing":"Prepare the superficial layers for chest wall. One layer at a time.","debrief":"Look again at any missed structure, then repeat the activity. Your next difficulty opens after a successful assessment.","objectives":[{"id":"chest-wall-3-0-2-fma7163","title":"Open skin","instruction":"Use the scalpel to cut an opening, then grip and lift skin to see underneath. Skin is the outside layer.","explanation":"skin opened. Examine the real structures beneath it.","targetId":"FMA7163","action":2,"narration":"anatomy-3-FMA7163-layer","equipmentState":"layer-opened","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[]},{"id":"chest-wall-3-0-2-rec_fat","title":"Open Subcutaneous tissue","instruction":"Use the scalpel to cut an opening, then grip and lift Subcutaneous tissue to see underneath. Fat sits below skin.","explanation":"Subcutaneous tissue opened. Examine the real structures beneath it.","targetId":"REC_fat","action":2,"narration":"anatomy-3-REC_fat-layer","equipmentState":"layer-opened","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["chest-wall-3-0-2-fma7163"]},{"id":"chest-wall-3-0-2-rec_fascia","title":"Open Thoracic fascia","instruction":"Use the scalpel to cut an opening, then grip and lift Thoracic fascia to see underneath. Fascia lies over muscle.","explanation":"Thoracic fascia opened. Examine the real structures beneath it.","targetId":"REC_fascia","action":2,"narration":"anatomy-3-REC_fascia-layer","equipmentState":"layer-opened","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["chest-wall-3-0-2-rec_fat"]}],"protectedIds":