INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('heart-coronaries-1-0', '2026.09.2', '{"id":"heart-coronaries-1-0","unitId":"heart-coronaries","version":"2026.09.2","mode":1,"difficulty":0,"ordered":true,"briefing":"Connect the heart wall, coronary vessels and neighboring great vessels.","debrief":"Look again at any missed structure, then repeat the activity. Your next difficulty opens after a successful assessment.","objectives":[{"id":"heart-coronaries-1-0-0-fma50039","title":"Find right coronary artery","instruction":"Point at right coronary artery and squeeze the trigger. Only one target is introduced at a time.","explanation":"right coronary artery identified · 1 of 3.","targetId":"FMA50039","action":0,"narration":"anatomy-1-FMA50039-easy","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[]},{"id":"heart-coronaries-1-0-0-fma50040","title":"Find left coronary artery","instruction":"Point at left coronary artery and squeeze the trigger. Only one target is introduced at a time.","explanation":"left coronary artery identified · 2 of 3.","targetId":"FMA50040","action":0,"narration":"anatomy-1-FMA50040-easy","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["heart-coronaries-1-0-0-fma50039"]},{"id":"heart-coronaries-1-0-0-fma4706","title":"Find coronary sinus","instruction":"Point at coronary sinus and squeeze the trigger. Only one target is introduced at a time.","explanation":"coronary sinus identified · 3 of 3.","targetId":"FMA4706","action":0,"narration":"anatomy-1-FMA4706-easy","equipmentState":"","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["heart-coronaries-1-0-0-fma50040"]}],"protectedIds":["REC_Left_Phrenic_nerve"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definitio