INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumothorax-0-0', '2026.09.2', '{"id":"pneumothorax-0-0","unitId":"pneumothorax","version":"2026.09.2","mode":0,"difficulty":0,"ordered":true,"briefing":"A breathless adult has a right pneumothorax. The case team has selected a small-bore chest drain. One coached step and one needed instrument are shown at a time.","debrief":"Air drains through the connected water seal. Recheck breathing, drain function and chest imaging; watch for pain, bleeding, infection or renewed breathlessness. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the collapsed lung","instruction":"Point to the right superior lobe. Compare its size with the opposite lung.","targetId":"MAL_RUL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-3-mal_rul-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumothorax-step-0"},{"title":"Check the patient and plan","instruction":"The chest image and indication are already established. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-3-mal_rul-hand-0"],"narration":"pneumothorax-step-1"},{"title":"Check the planned intercostal space","instruction":"Locate the upper edge of the lower rib on the cross-section. Avoid the bundle beneath the rib above.","targetId":"equipment:pleural-site","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-5-equipment-pleural-site-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-5-equipment-chart-probe-0"],"narration":"pneumothorax-step-2"},{"title":"Prepare a sterile field","instruction":"Move the swab onto the marked skin window. Hold the trigger to clean it; the sterile drape opens.","targetId":"equipment:pleural-site","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-6-equipment-pleural-site-swab-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-5-equipment-pleural-site-probe-0"],"narration":"pneumothorax-step-3"},{"title":"Represent local anaesthesia","instruction":"Place the anaesthetic syringe at the skin target. The case supplies the checked prescription.","targetId":"equipment:pleural-site","action":6,"toolId":"anaesthetic","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-6-equipment-pleural-site-anaesthetic-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-6-equipment-pleural-site-swab-0"],"narration":"pneumothorax-step-4"},{"title":"Confirm pleural access","instruction":"Guide the aspiration needle to the pleural-space endpoint. Air appears in the syringe before the wire step opens.","targetId":"equipment:pleural-end","action":5,"toolId":"needle","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-5-equipment-pleural-end-needle-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-6-equipment-pleural-site-anaesthetic-0"],"narration":"pneumothorax-step-5"},{"title":"Advance the guidewire","instruction":"Move the wire through each marker into the air space. Preserve the lung beyond the endpoint.","targetId":"equipment:pleural-end","action":7,"toolId":"guidewire","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-end-guidewire-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-5-equipment-pleural-end-needle-0"],"narration":"pneumothorax-step-6"},{"title":"Make the skin opening","instruction":"Move the scalpel along the short skin line beside the retained wire.","targetId":"equipment:pleural-incision","action":7,"toolId":"scalpel","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-incision-scalpel-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-end-guidewire-0"],"narration":"pneumothorax-step-7"},{"title":"Open the drain tract","instruction":"Advance the short dilator along the wire route. Stop at the endpoint; do not push toward the lung.","targetId":"equipment:pleural-end","action":7,"toolId":"dilator","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-end-dilator-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-incision-scalpel-0"],"narration":"pneumothorax-step-8"},{"title":"Place the drain over the wire","instruction":"Follow the same route with the drain. The training model then withdraws the wire and retains the drain.","targetId":"equipment:pleural-end","action":7,"toolId":"drain","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-end-drain-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-end-dilator-0"],"narration":"pneumothorax-step-9"},{"title":"Connect the water seal","instruction":"Fit the connector into the drain-bottle port. Keep the bottle below the chest.","targetId":"equipment:drain-circuit","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-4-equipment-drain-circuit-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-end-drain-0"],"narration":"pneumothorax-step-10"},{"title":"Fix the holding suture","instruction":"Follow the fixation loop around the drain with the needle holder. The holding suture secures the tube.","targetId":"equipment:pleural-fixation","action":7,"toolId":"suture","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-7-equipment-pleural-fixation-suture-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-0-4-equipment-drain-circuit-connector-0"],"narration":"pneumothorax-step-11"},{"title":"Secure the drain","instruction":"Place the fixation dressing over the entry site. Confirm the tube is secured.","targetId":"equipment:pleural-site","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-6-equipment-pleural-site-dressing-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-7-equipment-pleural-fixation-suture-0"],"narration":"pneumothorax-step-12"},{"title":"Check the response","instruction":"Touch the affected lobe with the assessment pointer. Inspect expansion and the connected drain.","targetId":"MAL_RUL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-0-8-mal_rul-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumothorax-0-0-6-equipment-pleural-site-dressing-0"],"narration":"pneumothorax-step-13"}],"protectedIds":["REC_Right_IC4_Nerve","REC_Right_IC4_Artery","FMA13295","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumothorax-0-1', '2026.09.2', '{"id":"pneumothorax-0-1","unitId":"pneumothorax","version":"2026.09.2","mode":0,"difficulty":1,"ordered":true,"briefing":"A breathless adult has a right pneumothorax. The case team has selected a small-bore chest drain. Use the findings to plan the sequence; most placement cues are removed.","debrief":"Air drains through the connected water seal. Recheck breathing, drain function and chest imaging; watch for pain, bleeding, infection or renewed breathlessness. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the collapsed lung","instruction":"Point to the right superior lobe. Compare its size with the opposite lung.","targetId":"MAL_RUL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-3-mal_rul-hand-0","essential":true,"weight":1,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumothorax-step-0"},{"title":"Check the patient and plan","instruction":"The chest image and indication are already established. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumothorax-0-1-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumothorax-0-1-3-mal_rul-hand-0"],"narration":"pneumothorax-step-1"},{"title":"Check the planned intercostal space","instruction":"Locate the upper edge of the lower rib on the cross-section. Avoid the bundle beneath the rib above.