INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('asthma-0-0', '2026.09.2', '{"id":"asthma-0-0","unitId":"asthma","version":"2026.09.2","mode":0,"difficulty":0,"ordered":true,"briefing":"An adult with airway narrowing has a prescribed metered-dose inhaler and spacer. Help the virtual patient use it. One coached step and one needed instrument are shown at a time.","debrief":"The airway opens as prescribed reliever treatment takes effect. Reassess breathing and technique; the patient still needs an asthma action plan. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the narrowed airway","instruction":"Select the right main bronchus. Look into the enlarged airway beside the specimen.","targetId":"FMA68418","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-3-fma68418-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"asthma-step-0"},{"title":"Check the patient and plan","instruction":"Confirm the prescribed device and medicine. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-3-fma68418-hand-0"],"narration":"asthma-step-1"},{"title":"Remove the cap","instruction":"Grip the cap and pull it away along the short arrow. Inspect the open mouthpiece.","targetId":"equipment:inhaler-cap","action":7,"toolId":"cap","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-7-equipment-inhaler-cap-cap-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["asthma-0-0-5-equipment-chart-probe-0"],"narration":"asthma-step-2"},{"title":"Shake the inhaler","instruction":"Grip the inhaler. Move it through the three shake markers.","targetId":"equipment:inhaler-prep","action":7,"toolId":"inhaler","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-7-equipment-inhaler-prep-inhaler-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["asthma-0-0-7-equipment-inhaler-cap-cap-0"],"narration":"asthma-step-3"},{"title":"Fit the inhaler to the spacer","instruction":"Insert the inhaler mouthpiece into the rear of the spacer.","targetId":"equipment:spacer","action":4,"toolId":"inhaler","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-4-equipment-spacer-inhaler-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-7-equipment-inhaler-prep-inhaler-0"],"narration":"asthma-step-4"},{"title":"Seal the mouthpiece","instruction":"Let the virtual patient breathe out away from the spacer, then hold the mouthpiece against the lips.","targetId":"equipment:mouthpiece","action":5,"toolId":"spacer","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-5-equipment-mouthpiece-spacer-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-4-equipment-spacer-inhaler-0"],"narration":"asthma-step-5"},{"title":"Release one puff","instruction":"Press once with the inhaler aligned at the spacer. One dose enters the chamber.","targetId":"equipment:spacer","action":6,"toolId":"inhaler","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-6-equipment-spacer-inhaler-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-5-equipment-mouthpiece-spacer-0"],"narration":"asthma-step-6"},{"title":"Guide a slow breath in","instruction":"Keep the mouthpiece sealed during the green inspiration phase. The virtual patient then pauses comfortably before breathing out.","targetId":"equipment:mouthpiece","action":5,"toolId":"spacer","equipmentState":"inspiration","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-5-equipment-mouthpiece-spacer-1","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-6-equipment-spacer-inhaler-0"],"narration":"asthma-step-7"},{"title":"Check breathing and technique","instruction":"Touch the bronchus with the assessment pointer. Compare the airway opening and review the action plan.","targetId":"FMA68418","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"asthma-0-0-8-fma68418-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-5-equipment-mouthpiece-spacer-1"],"narration":"asthma-step-8"}],"protectedIds":["FMA7131"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
