INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumonia-0-0', '2026.09.2', '{"id":"pneumonia-0-0","unitId":"pneumonia","version":"2026.09.2","mode":0,"difficulty":0,"ordered":true,"briefing":"An adult has confirmed bacterial pneumonia, prescribed antibiotics and an oxygen order for hypoxaemia. One coached step and one needed instrument are shown at a time.","debrief":"Review response and microbiology. Review intravenous treatment by 48 hours. Fever often settles before cough and fatigue; persistent or worsening symptoms need reassessment. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the affected lobe","instruction":"Select the right inferior lobe. Compare air spaces with the clear neighboring tissue.","targetId":"MAL_RLL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-3-mal_rll-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumonia-step-0"},{"title":"Check the patient and plan","instruction":"Review severity, allergies and the written antibiotic and oxygen orders. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-3-mal_rll-hand-0"],"narration":"pneumonia-step-1"},{"title":"Record a respiratory baseline","instruction":"Place the monitoring probe on the virtual patient''s finger. Review the qualitative breathing and oxygenation indicators.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-5-equipment-monitor-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-5-equipment-chart-probe-0"],"narration":"pneumonia-step-2"},{"title":"Check the medication order","instruction":"Touch the prescription dock with the labeled medicine. Match patient, medicine, route and the supplied order.","targetId":"equipment:prescribed-care","action":5,"toolId":"medication","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-5-equipment-prescribed-care-medication-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-5-equipment-monitor-probe-0"],"narration":"pneumonia-step-3"},{"title":"Prepare the prescribed route","instruction":"Join the prepared administration set to its labeled port.","targetId":"equipment:prescribed-care","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-4-equipment-prescribed-care-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-5-equipment-prescribed-care-medication-0"],"narration":"pneumonia-step-4"},{"title":"Administer the ordered treatment","instruction":"Seat the checked medicine in its administration port. Hold the trigger to represent the prescribed administration.","targetId":"equipment:prescribed-care","action":6,"toolId":"medication","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-6-equipment-prescribed-care-medication-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-4-equipment-prescribed-care-connector-0"],"narration":"pneumonia-step-5"},{"title":"Apply the oxygen order","instruction":"Fit the support mask to the virtual patient. The case uses its supplied oxygen order.","targetId":"equipment:mouthpiece","action":6,"toolId":"oxygen","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-6-equipment-mouthpiece-oxygen-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-6-equipment-prescribed-care-medication-0"],"narration":"pneumonia-step-6"},{"title":"Recheck respiratory support","instruction":"Return the monitoring probe to the finger. Compare the response with baseline.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-5-equipment-monitor-probe-1","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-6-equipment-mouthpiece-oxygen-0"],"narration":"pneumonia-step-7"},{"title":"Review the follow-up timeline","instruction":"Probe the affected lobe. Watch the days-and-weeks timeline; recovery is gradual.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-0-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-5-equipment-monitor-probe-1"],"narration":"pneumonia-step-8"}],"protectedIds":["REC_Right_Phrenic_nerve"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumonia-0-1', '2026.09.2', '{"id":"pneumonia-0-1","unitId":"pneumonia","version":"2026.09.2","mode":0,"difficulty":1,"ordered":true,"briefing":"An adult has confirmed bacterial pneumonia, prescribed antibiotics and an oxygen order for hypoxaemia. Use the findings to plan the sequence; most placement cues are removed.","debrief":"Review response and microbiology. Review intravenous treatment by 48 hours. Fever often settles before cough and fatigue; persistent or worsening symptoms need reassessment. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the affected lobe","instruction":"Select the right inferior lobe. Compare air spaces with the clear neighboring tissue.","targetId":"MAL_RLL","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-3-mal_rll-hand-0","essential":true,"weight":1,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumonia-step-0"},{"title":"Check the patient and plan","instruction":"Review severity, allergies and the written antibiotic and oxygen orders. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-3-mal_rll-hand-0"],"narration":"pneumonia-step-1"},{"title":"Record a respiratory baseline","instruction":"Place the monitoring probe on the virtual patient''s finger. Review the qualitative breathing and oxygenation indicators.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-5-equipment-monitor-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-5-equipment-chart-probe-0"],"narration":"pneumonia-step-2"},{"title":"Check the medication order","instruction":"Touch the prescription dock with the labeled medicine. Match patient, medicine, route and the supplied order.","targetId":"equipment:prescribed-care","action":5,"toolId":"medication","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-5-equipment-prescribed-care-medication-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-5-equipment-monitor-probe-0"],"narration":"pneumonia-step-3"},{"title":"Prepare the prescribed route","instruction":"Join the prepared administration set to its labeled port.","targetId":"equipment:prescribed-care","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-4-equipment-prescribed-care-connector-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-5-equipment-prescribed-care-medication-0"],"narration":"pneumonia-step-4"},{"title":"Administer the ordered treatment","instruction":"Seat the checked medicine in its administration port. Hold the trigger to represent the prescribed administration.","targetId":"equipment:prescribed-care","action":6,"toolId":"medication","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-6-equipment-prescribed-care-medication-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-4-equipment-prescribed-care-connector-0"],"narration":"pneumonia-step-5"},{"title":"Apply the oxygen order","instruction":"Fit the support mask to the virtual patient. The case uses its supplied oxygen order.","targetId":"equipment:mouthpiece","action":6,"toolId":"oxygen","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-6-equipment-mouthpiece-oxygen-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-6-equipment-prescribed-care-medication-0"],"narration":"pneumonia-step-6"},{"title":"Recheck respiratory support","instruction":"Return the monitoring probe to the finger. Compare the response with baseline.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-5-equipment-monitor-probe-1","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-6-equipment-mouthpiece-oxygen-0"],"narration":"pneumonia-step-7"},{"title":"Review the follow-up timeline","instruction":"Probe the affected lobe. Watch the days-and-weeks timeline; recovery is gradual.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pneumonia-0-1-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pneumonia-0-1-5-equipment-monitor-probe-1"],"narration":"pneumonia-step-8"}],"protectedIds":["REC_Right_Phrenic_nerve"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
