step-8"},{"title":"Withdraw and dress the site","instruction":"Withdraw the aspiration catheter along the return markers. The dressing is applied after removal.","targetId":"equipment:pleural-withdrawal","action":7,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-1-7-equipment-pleural-withdrawal-aspirator-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0.95,"prerequisites":["pleural-effusion-0-1-5-equipment-monitor-probe-0"],"narration":"pleural-effusion-step-9"},{"title":"Review symptoms and the cause","instruction":"Probe the right lower lobe. Compare expansion and review the fluid investigation plan.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-1-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.05,"maxAngle":35,"minContactSeconds":0.9,"minPathFraction":0,"prerequisites":["pleural-effusion-0-1-7-equipment-pleural-withdrawal-aspirator-0"],"narration":"pleural-effusion-step-10"}],"protectedIds":["FMA13295","REC_Right_IC6_Nerve","REC_Right_IC6_Artery","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pleural-effusion-0-2', '2026.09.2', '{"id":"pleural-effusion-0-2","unitId":"pleural-effusion","version":"2026.09.2","mode":0,"difficulty":2,"ordered":true,"briefing":"A symptomatic right pleural collection has been selected for ultrasound-guided therapeutic aspiration. Work independently, identify unsafe actions and reassess the response.","debrief":"Fluid removal relieves compression in this case. Monitor symptoms and the puncture site; send the planned sample and investigate why fluid accumulated. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the pleural collection","instruction":"Select the right parietal pleura. Identify fluid outside the lower lung.","targetId":"REC_Right_Parietal_Pleura","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-3-rec_right_parietal_pleura-hand-0","essential":true,"weight":1,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pleural-effusion-step-0"},{"title":"Check the patient and plan","instruction":"Review the aspiration indication and bleeding-risk assessment. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-3-rec_right_parietal_pleura-hand-0"],"narration":"pleural-effusion-step-1"},{"title":"Locate fluid with ultrasound","instruction":"Hold the ultrasound probe at the side-window. Identify fluid above the diaphragm and outside the lung.","targetId":"equipment:pleural-site","action":5,"toolId":"ultrasound","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-5-equipment-pleural-site-ultrasound-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-5-equipment-chart-probe-0"],"narration":"pleural-effusion-step-2"},{"title":"Prepare the skin","instruction":"Use the swab over the ultrasound-selected window.","targetId":"equipment:pleural-site","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-6-equipment-pleural-site-swab-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-5-equipment-pleural-site-ultrasound-0"],"narration":"pleural-effusion-step-3"},{"title":"Represent local anaesthesia","instruction":"Place the checked anaesthetic syringe at the entry target.","targetId":"equipment:pleural-site","action":6,"toolId":"anaesthetic","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-6-equipment-pleural-site-anaesthetic-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-6-equipment-pleural-site-swab-0"],"narration":"pleural-effusion-step-4"},{"title":"Prepare controlled aspiration","instruction":"Connect the syringe and collection circuit. This case uses controlled aspiration without wall suction.","targetId":"equipment:aspiration","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-4-equipment-aspiration-connector-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-6-equipment-pleural-site-anaesthetic-0"],"narration":"pleural-effusion-step-5"},{"title":"Advance the aspiration catheter","instruction":"Follow the short channel above the lower rib. Stop in the fluid; preserve deeper lung and diaphragm.","targetId":"equipment:pleural-end","action":7,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-7-equipment-pleural-end-aspirator-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["pleural-effusion-0-2-4-equipment-aspiration-connector-0"],"narration":"pleural-effusion-step-6"},{"title":"Begin slow aspiration","instruction":"Hold the aspiration control and watch the fluid fall. A symptom cue will ask you to pause.","targetId":"equipment:pleural-end","action":6,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-6-equipment-pleural-end-aspirator-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-7-equipment-pleural-end-aspirator-0"],"narration":"pleural-effusion-step-7"},{"title":"Stop and check new chest discomfort","instruction":"Release aspiration. Touch the monitoring station with the probe to record the symptom check.","targetId":"equipment:monitor","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-5-equipment-monitor-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-6-equipment-pleural-end-aspirator-0"],"narration":"pleural-effusion-step-8"},{"title":"Withdraw and dress the site","instruction":"Withdraw the aspiration catheter along the return markers. The dressing is applied after removal.","targetId":"equipment:pleural-withdrawal","action":7,"toolId":"aspirator","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-7-equipment-pleural-withdrawal-aspirator-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["pleural-effusion-0-2-5-equipment-monitor-probe-0"],"narration":"pleural-effusion-step-9"},{"title":"Review symptoms and the cause","instruction":"Probe the right lower lobe. Compare expansion and review the fluid investigation plan.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"pleural-effusion-0-2-8-mal_rll-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pleural-effusion-0-2-7-equipment-pleural-withdrawal-aspirator-0"],"narration":"pleural-effusion-step-10"}],"protectedIds":["FMA13295","REC_Right_IC6_Nerve","REC_Right_IC6_Artery","MAL_RLL"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('aortic-stenosis-0-0', '2026.09.2', '{"id":"aortic-stenosis-0-0","unitId":"aortic-stenosis","version":"2026.09.2","mode":0,"difficulty":0,"ordered":true,"briefing":"A heart team has selected transfemoral TAVI for severe aortic stenosis in a fictional adult. One coached step and one needed instrument are shown at a time.","debrief":"The replacement opens within the native valve. Continue rhythm, valve and groin-site monitoring; watch for leakage, bleeding, stroke symptoms and conduction problems. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the restricted valve","instruction":"Select the anterior aortic cusp. Watch the reduced opening in the cutaway.","targetId":"FMA7253","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-3-fma7253-hand-0","essential":true,"weight":1,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"aortic-stenosis-step-0"},{"title":"Check the patient and plan","instruction":"Review the heart-team decision and the planned CT-sized device. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-3-fma7253-hand-0"],"narration":"aortic-stenosis-step-1"},{"title":"Prepare femoral access","instruction":"Use the swab at the groin target. Local anaesthesia and access preparation are represented.","targetId":"equipment:femoral-access","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-6-equipment-femoral-access-swab-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-5-equipment-chart-probe-0"],"narration":"aortic-stenosis-step-2"},{"title":"Prepare the delivery system","instruction":"Connect the device handle to the femoral sheath port.","targetId":"equipment:valve-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-4-equipment-valve-system-connector-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-6-equipment-femoral-access-swab-0"],"narration":"aortic-stenosis-step-3"},{"title":"Follow the aorta to the valve","instruction":"Follow femoral, iliac, abdominal aorta, descending aorta, arch and ascending aorta markers to the valve.","targetId":"equipment:aortic-valve","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-7-equipment-aortic-valve-guidewire-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-0-4-equipment-valve-system-connector-0"],"narration":"aortic-stenosis-step-4"},{"title":"Align the replacement valve","instruction":"Place the delivery tip across the native valve. Keep the coronary openings unobstructed.","targetId":"equipment:aortic-valve","action":5,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-5-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-7-equipment-aortic-valve-guidewire-0"],"narration":"aortic-stenosis-step-5"},{"title":"Deploy inside the native valve","instruction":"Activate the selected self-expanding replacement. The old cusps remain around its scaffold.","targetId":"equipment:aortic-valve","action":6,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-6-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-5-equipment-aortic-valve-valve-0"],"narration":"aortic-stenosis-step-6"},{"title":"Check position and forward flow","instruction":"Use the assessment pointer at the implanted valve. Review opening, leakage and the coronary relationship.","targetId":"equipment:aortic-valve","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-5-equipment-aortic-valve-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-6-equipment-aortic-valve-valve-0"],"narration":"aortic-stenosis-step-7"},{"title":"Withdraw the delivery system","instruction":"Return the delivery handle along the withdrawal path, leaving the replacement in place.","targetId":"equipment:valve-withdrawal","action":7,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-7-equipment-valve-withdrawal-valve-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-0-5-equipment-aortic-valve-probe-0"],"narration":"aortic-stenosis-step-8"},{"title":"Close and inspect femoral access","instruction":"Place the closure dressing at the groin site and inspect the access model.","targetId":"equipment:femoral-access","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-6-equipment-femoral-access-dressing-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-7-equipment-valve-withdrawal-valve-0"],"narration":"aortic-stenosis-step-9"},{"title":"Review valve and rhythm follow-up","instruction":"Probe the aortic cusp. Check the represented forward flow and post-procedure monitoring plan.","targetId":"FMA7253","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-0-8-fma7253-probe-0","essential":true,"weight":2,"maxDistance":0.075,"maxAngle":55,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-6-equipment-femoral-access-dressing-0"],"narration":"aortic-stenosis-step-10"}],"protectedIds":["FMA50040","FMA50039"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
