INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('aortic-stenosis-0-2', '2026.09.2', '{"id":"aortic-stenosis-0-2","unitId":"aortic-stenosis","version":"2026.09.2","mode":0,"difficulty":2,"ordered":true,"briefing":"A heart team has selected transfemoral TAVI for severe aortic stenosis in a fictional adult. Work independently, identify unsafe actions and reassess the response.","debrief":"The replacement opens within the native valve. Continue rhythm, valve and groin-site monitoring; watch for leakage, bleeding, stroke symptoms and conduction problems. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Find the restricted valve","instruction":"Select the anterior aortic cusp. Watch the reduced opening in the cutaway.","targetId":"FMA7253","action":3,"toolId":"","equipmentState":"","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-3-fma7253-hand-0","essential":true,"weight":1,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"aortic-stenosis-step-0"},{"title":"Check the patient and plan","instruction":"Review the heart-team decision and the planned CT-sized device. Touch the chart with the assessment pointer. Check identity, consent, allergies and the agreed treatment.","targetId":"equipment:chart","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-5-equipment-chart-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-3-fma7253-hand-0"],"narration":"aortic-stenosis-step-1"},{"title":"Prepare femoral access","instruction":"Use the swab at the groin target. Local anaesthesia and access preparation are represented.","targetId":"equipment:femoral-access","action":6,"toolId":"swab","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-6-equipment-femoral-access-swab-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-5-equipment-chart-probe-0"],"narration":"aortic-stenosis-step-2"},{"title":"Prepare the delivery system","instruction":"Connect the device handle to the femoral sheath port.","targetId":"equipment:valve-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-4-equipment-valve-system-connector-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-6-equipment-femoral-access-swab-0"],"narration":"aortic-stenosis-step-3"},{"title":"Follow the aorta to the valve","instruction":"Follow femoral, iliac, abdominal aorta, descending aorta, arch and ascending aorta markers to the valve.","targetId":"equipment:aortic-valve","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-7-equipment-aortic-valve-guidewire-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-2-4-equipment-valve-system-connector-0"],"narration":"aortic-stenosis-step-4"},{"title":"Align the replacement valve","instruction":"Place the delivery tip across the native valve. Keep the coronary openings unobstructed.","targetId":"equipment:aortic-valve","action":5,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-5-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-7-equipment-aortic-valve-guidewire-0"],"narration":"aortic-stenosis-step-5"},{"title":"Deploy inside the native valve","instruction":"Activate the selected self-expanding replacement. The old cusps remain around its scaffold.","targetId":"equipment:aortic-valve","action":6,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-6-equipment-aortic-valve-valve-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-5-equipment-aortic-valve-valve-0"],"narration":"aortic-stenosis-step-6"},{"title":"Check position and forward flow","instruction":"Use the assessment pointer at the implanted valve. Review opening, leakage and the coronary relationship.","targetId":"equipment:aortic-valve","action":5,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-5-equipment-aortic-valve-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-6-equipment-aortic-valve-valve-0"],"narration":"aortic-stenosis-step-7"},{"title":"Withdraw the delivery system","instruction":"Return the delivery handle along the withdrawal path, leaving the replacement in place.","targetId":"equipment:valve-withdrawal","action":7,"toolId":"valve","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-7-equipment-valve-withdrawal-valve-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["aortic-stenosis-0-2-5-equipment-aortic-valve-probe-0"],"narration":"aortic-stenosis-step-8"},{"title":"Close and inspect femoral access","instruction":"Place the closure dressing at the groin site and inspect the access model.","targetId":"equipment:femoral-access","action":6,"toolId":"dressing","equipmentState":"connected","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-6-equipment-femoral-access-dressing-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-7-equipment-valve-withdrawal-valve-0"],"narration":"aortic-stenosis-step-9"},{"title":"Review valve and rhythm follow-up","instruction":"Probe the aortic cusp. Check the represented forward flow and post-procedure monitoring plan.","targetId":"FMA7253","action":8,"toolId":"probe","equipmentState":"ready","explanation":"Step complete. Follow the next single instruction.","id":"aortic-stenosis-0-2-8-fma7253-probe-0","essential":true,"weight":2,"maxDistance":0.03,"maxAngle":22,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-2-6-equipment-femoral-access-dressing-0"],"narration":"aortic-stenosis-step-10"}],"protectedIds":["FMA50040","FMA50039"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
